K=10; dt=0.001*K
D={f:pd.read_csv(f).iloc[::K].reset_index(drop=True) for f in files}
for f,d in D.items():
    th=d.bus_angle_rad.values
    w=np.gradient(th,dt)/(2*np.pi*60)
    d['w']=w
def simp(p,d):
    Kw,Tw,Kpv,Tp=p
    V=d.voltage_pu.values; w=d.w.values
    P0=d.active_power_pu.values[0]; V0=V[0]
    # P = P0 + Kpv*(V-V0) - Kw*wf, wf = lagged freq
    wf=np.zeros(len(w)); a=dt/(Tw+dt)
    for i in range(1,len(w)): wf[i]=wf[i-1]+a*(w[i]-wf[i-1])
    Pm=P0+Kpv*(V-V0)-Kw*wf
    return Pm
def resp(p):
